CREATE TABLE CORE.T_DIM_CAL_MONTH_2 (
	CY_MONTH NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 month as a number of the form YYYYMM, where YYYY is the calendar_2 year and MM_2 is month of the calendar_2 year.',
	CY NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 year as a number in the form YYYY. Eg. 2019',
	BUS_YEAR NUMBER(38,0) NOT NULL COMMENT 'The business year as a number in the form YYYY. Eg. 2019.',
	MONTH_OF_YEAR NUMBER(38,0) NOT NULL COMMENT 'The month of the calendar_2 year as a number using the convention January = 1 ... December = 12.',
	MONTH_OF_BUS_YEAR NUMBER(38,0) NOT NULL COMMENT 'The month of the (Lidl) business year (starting in March) as a number using the convention March = 1, April = 2 ... December = 10, January = 11, February = 12. ',
	MONTH_OF_YEAR_SHORT_NAME VARCHAR(100) NOT NULL COMMENT 'The short name / abbreviation for month of the year in group language, i.e. in German.',
	MONTH_OF_YEAR_SHORT_NAME_DE VARCHAR(100) COMMENT 'The short name / abbreviation for month of the year in German.',
	MONTH_OF_YEAR_SHORT_NAME_EN VARCHAR(100) COMMENT 'The short name / abbreviation for month of the year in English.',
	MONTH_OF_YEAR_NAME VARCHAR(100) NOT NULL COMMENT 'The full name for the month of the year in group language, i.e. in German.',
	MONTH_OF_YEAR_NAME_DE VARCHAR(100) COMMENT 'The full name for the month of the year in German.',
	MONTH_OF_YEAR_NAME_EN VARCHAR(100) COMMENT 'The full name for the month of the year in English.',
	CY_MONTH_BEGIN_DT DATE NOT NULL COMMENT 'The first day of the month in the form YYYY-MM_2-DD. Eg. 2019-05-01 for May 2019.',
	CY_MONTH_END_DT DATE NOT NULL COMMENT 'The last day of the month in the form YYYY-MM_2-DD. Eg. 2019-05-31 for May 2019.',
	CY_MONTH_DAY_CNT NUMBER(38,0) COMMENT 'The number of days that this month contains. (28 / 29 / 30 / 31)',
	CY_MONTH_PREV_1M NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 month one month ago as a number in the form YYYYMM. Eg. 201901.',
	CY_MONTH_PREV_1Y NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 month one year ago as a number in the form YYYYMM. Eg. 201802.',
	CY_MONTH_PREV_2Y NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 month two years ago as a number in the form YYYYMM. Eg. 201702.',
	CY_MONTH_PREV_3Y NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 month three years ago as a number in the form YYYYMM. Eg. 201602.',
	CY_MONTH_PREV_4Y NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 month four years ago as a number in the form YYYYMM. Eg. 201502. ',
	CY_MONTH_PREV_5Y NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 month five years ago as a number in the form YYYYMM. Eg. 201402.',
	CY_MONTH_OFFSET NUMBER(38,0) COMMENT 'The difference in months between this calendar_2 month and the current month. So if current calendar_2 month is 201901, then the offset is 0 for 201901, -1 for 201812 and +1 for 201902.',
	CY_OFFSET NUMBER(38,0) COMMENT 'The difference in years between the calendar_2 year to which this month belongs, and the current calendar_2 year. So if the current calendar_2 year is 2019, then the offset is 0 for 2019, -1 for 2018 and +1 for 2020.',
	BUS_YEAR_OFFSET NUMBER(38,0) COMMENT 'The difference in years between the business year to which this month belongs, and the current business year. So if the current business year is 2019 then the offset is 0 for 2019, -1 for 2018 and +1 for 2020.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was inserted into the table.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last modified. (In case the record has not been modified since its creation, dwh_updated is identical to dwh_created.)',
	DWH_SRC_FILE_NAME                   VARCHAR(255)    COMMENT 'The path and the name of the file(s) from which this record was loaded.',
    SRC_FILE_TMSP                       TIMESTAMP_LTZ   COMMENT 'The point in time when this record was extracted from the source.',
	CY_MONTH_NAME_DE VARCHAR(100) COMMENT 'The year and full name of month in German',
	CY_MONTH_NAME_EN VARCHAR(100) COMMENT 'The year and full name of month in English.',
    CONSTRAINT PK_T_DIM_CAL_MONTH PRIMARY KEY (CY_MONTH) NOT ENFORCED
)COMMENT='The month dimension contains one record for each month in the calendar.'
;